eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   blogCategories: () => (/* binding */ blogCategories)\n/* harmony export */ });\n/* harmony import */ var _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! __barrel_optimize__?names=BookOpen,Brain,Rocket,Server!=!lucide-react */ \"(ssr)/./node_modules/lucide-react/dist/esm/icons/brain.js\");\n/* harmony import */ var _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_1__ = __webpack_require__(/*! __barrel_optimize__?names=BookOpen,Brain,Rocket,Server!=!lucide-react */ \"(ssr)/./node_modules/lucide-react/dist/esm/icons/server.js\");\n/* harmony import */ var _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_2__ = __webpack_require__(/*! __barrel_optimize__?names=BookOpen,Brain,Rocket,Server!=!lucide-react */ \"(ssr)/./node_modules/lucide-react/dist/esm/icons/rocket.js\");\n/* harmony import */ var _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_3__ = __webpack_require__(/*! __barrel_optimize__?names=BookOpen,Brain,Rocket,Server!=!lucide-react */ \"(ssr)/./node_modules/lucide-react/dist/esm/icons/book-open.js\");\n// // lib/blogCategories.ts\n\nconst blogCategories = {\n    \"ai-tech\": {\n        label: \"AI & Tech\",\n        icon: _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_0__[\"default\"],\n        gradient: \"from-[#1B2A6B] via-[#2451C4] to-[#22C4F5]\",\n        image: \"/ai-tech.png\"\n    },\n    engineering: {\n        label: \"Engineering\",\n        icon: _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_1__[\"default\"],\n        gradient: \"from-[#2A1B6B] via-[#4A1FA0] to-[#7B3FE4]\",\n        image: \"/engineering.png\"\n    },\n    product: {\n        label: \"Product\",\n        icon: _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_2__[\"default\"],\n        gradient: \"from-[#0F3B6B] via-[#1E63A8] to-[#3E7BFA]\",\n        image: \"/product.png\"\n    },\n    company: {\n        label: \"Company\",\n        icon: _barrel_optimize_names_BookOpen_Brain_Rocket_Server_lucide_react__WEBPACK_IMPORTED_MODULE_3__[\"default\"],\n        gradient: \"from-[#111B46] via-[#273EA8] to-[#7C3AED]\",\n        image: \"/company.png\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/blogCategories.ts\n");

